import {hydrateZetaImages} from './zeta-images';
/** Reads plot metadata and image assets from the uncompressed ZIP generated by zetaWeb Plus. */
function backupEntries(buffer:ArrayBuffer){
 const bytes=new Uint8Array(buffer),v=new DataView(buffer);let offset=0;const entries=new Map<string,Uint8Array>();
 if(bytes.length>30*1024*1024)throw Error('バックアップは30MB以内にしてください');
 while(offset+4<=bytes.length&&v.getUint32(offset,true)===0x04034b50){
  if(offset+30>bytes.length)throw Error('ZIPが破損しています');
  const flags=v.getUint16(offset+6,true),method=v.getUint16(offset+8,true),size=v.getUint32(offset+18,true),raw=v.getUint32(offset+22,true),nameLength=v.getUint16(offset+26,true),extra=v.getUint16(offset+28,true),start=offset+30+nameLength+extra,end=start+size;
  if(flags&9||method!==0||raw!==size)throw Error('zetaWeb Plusが保存したZIPか、展開したplot.jsonを選んでください');
  if(end>bytes.length)throw Error('ZIPが破損しています');
  const name=new TextDecoder().decode(bytes.subarray(offset+30,offset+30+nameLength));
  if(name==='plot.json'||name==='assets.json'||/^images\/[^/]+$/.test(name)){
   if(entries.has(name)||size>(name.startsWith('images/')?10*1024*1024:1500000))throw Error('作品情報が重複しているか大きすぎます');
   let crc=0xffffffff;for(const byte of bytes.subarray(start,end)){crc^=byte;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}
   if(((crc^0xffffffff)>>>0)!==v.getUint32(offset+14,true))throw Error('作品情報が破損しています');
   entries.set(name,bytes.slice(start,end));
  }
  offset=end;
 }
 if(!entries.has('plot.json'))throw Error('ZIPにplot.jsonがありません');return entries;
}
export function plotFromBackup(buffer:ArrayBuffer):unknown{return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(backupEntries(buffer).get('plot.json')));}
export async function readZetaFile(file:File,kind:'plot'|'history'){
 if(kind==='plot'&&file.name.toLowerCase().endsWith('.zip')){if(file.size>30*1024*1024)throw Error('バックアップは30MB以内にしてください');const entries=backupEntries(await file.arrayBuffer());const plot=JSON.parse(new TextDecoder().decode(entries.get('plot.json')));const manifest=JSON.parse(new TextDecoder().decode(entries.get('assets.json')||new TextEncoder().encode('[]')));const assets=new Map<string,Uint8Array>();if(Array.isArray(manifest))for(const a of manifest){if(a.status==='saved'&&entries.has(a.file))assets.set(a.url,entries.get(a.file)!);}return hydrateZetaImages(plot,assets);}
 if(file.size>1500000)throw Error('JSONファイルは1.5MB以内にしてください');return hydrateZetaImages(JSON.parse(await file.text()));
}
